def get_resolver(urlconf=None):
    if urlconf is None:
        urlconf = settings.ROOT_URLCONF
    return _get_cached_resolver(urlconf)


# A single cached resolver per urlconf key. The resolver is version-aware:
# replacing the ``urlpatterns`` exposed by a hashable urlconf object retires
# the entry built for the previous routing table (a *refresh*), so an explicit
# urlconf passed to resolve() observes the replacement without the caller
# having to clear any internal cache.
_resolver_cache: dict = {}


def _get_cached_resolver(urlconf=None):
    try:
        hash(urlconf)
    except TypeError:
        # An unhashable urlconf (a plain list/tuple of patterns handed in by
        # the caller) is ephemeral: it cannot be used as a cache key and must
        # not be shared with a later call that happens to pass an equal
        # object. Build a dedicated resolver instead of caching it.
        return URLResolver(RegexPattern(r"^/"), urlconf)
    version = _urlconf_version(urlconf)
    key = (urlconf, version)
    try:
        resolver = _resolver_cache[key]
    except KeyError:
        resolver = URLResolver(RegexPattern(r"^/"), urlconf)
        _resolver_cache[key] = resolver
    return resolver


def _urlconf_version(urlconf):
    """
    Identify the current routing table of *urlconf*.

    A replaced ``urlpatterns`` attribute yields a different version, so the
    cached resolver built for the previous table is never reused. A dotted
    path is identified by the module object actually imported (module reload
    replaces ``sys.modules``) together with its ``__dict__`` state; modules
    never mutate their patterns in place, so this costs only an identity
    check on the hot path.
    """
    if isinstance(urlconf, str):
        try:
            module = sys.modules.get(urlconf)
        except Exception:
            module = None
        if module is None:
            # Import side effects (registering converters and so on) must
            # still run before the resolver is constructed.
            return (urlconf, False)
        return (id(module), id(module.__dict__))
    return (type(urlconf).__qualname__, id(urlconf), id(vars(urlconf)))

