def get_resolver(urlconf=None):
    if urlconf is None:
        urlconf = settings.ROOT_URLCONF
    return _get_cached_resolver(urlconf)


# The resolver cache is keyed by (urlconf, version). A replaced ``urlpatterns``
# attribute on a hashable urlconf object changes its version and therefore
# retires the resolver built for the previous routing table (a *refresh*), so
# an explicit urlconf handed to resolve() observes the replacement without the
# caller having to clear any internal cache.
_resolver_cache: dict = {}


def _get_cached_resolver(urlconf=None):
    try:
        hash(urlconf)
    except TypeError:
        # An unhashable urlconf (a plain list/tuple of patterns handed in by
        # the caller) is ephemeral: it cannot be used as a cache key and must
        # not be shared with a later call that happens to pass an equal
        # object. Build a dedicated resolver instead of caching it.
        return URLResolver(RegexPattern(r"^/"), urlconf)
    version = _urlconf_version(urlconf)
    if version is None:
        # The module has not been imported yet. Import it now so the version
        # stays stable for later calls instead of changing on first use.
        import_module(urlconf)
        version = _urlconf_version(urlconf)
    key = (urlconf, version)
    try:
        resolver = _resolver_cache[key]
    except KeyError:
        resolver = URLResolver(RegexPattern(r"^/"), urlconf)
        _resolver_cache[key] = resolver
    return resolver


