def _reload_patterns(self, force=False):
    """
    Make sure the cached urlconf module and its urlpatterns reflect the
    urlconf's current routing table.

    The routing table of a caller-supplied urlconf may be replaced at
    runtime (observable configuration refresh). When it is, the previously
    loaded patterns, together with every cache derived from them (reverse
    lookups, namespaces and callback strings), are discarded and rebuilt
    from the new table on demand; callers never have to clear a cache
    themselves. A refresh triggered by a table that fails to load never
    disturbs the previously working table.
    """
    version = self._urlconf_version(self.urlconf_name)
    if not force and version == self._urlconf_version_cache:
        return
    if isinstance(self.urlconf_name, str):
        urlconf_module = import_module(self.urlconf_name)
    else:
        urlconf_module = self.urlconf_name
    patterns = getattr(urlconf_module, "urlpatterns", urlconf_module)
    try:
        iter(patterns)
    except TypeError as e:
        msg = (
            "The included URLconf '{name}' does not appear to have "
            "any patterns in it. If you see the 'urlpatterns' variable "
            "with valid patterns in the file then the issue is probably "
            "caused by a circular import."
        )
        # Raising discards nothing: the previously cached patterns stay in
        # place, so a still-valid old table keeps resolving.
        raise ImproperlyConfigured(
            msg.format(name=self.urlconf_name)
        ) from e
    # Only commit the refresh once the new table has loaded successfully.
    self._cached_urlconf_module = urlconf_module
    self._cached_url_patterns = patterns
    self._urlconf_version_cache = version
    self._reverse_dict = {}
    self._namespace_dict = {}
    self._app_dict = {}
    self._callback_strs = set()
    self._populated = False

